## 🔹 5. API Endpoint (Recommend Movies)

```js
// api/recommend.js
import { GoogleGenerativeAI } from "@google/generative-ai";
import { createClient } from "@supabase/supabase-js";

const genAI = new GoogleGenerativeAI(process.env.GEMINI_API_KEY);
const supabase = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_KEY);

async function embedAnswer(answer) {
  const model = genAI.getGenerativeModel({ model: "embedding-001" });
  const result = await model.embedContent(answer);
  return result.embedding.values;
}

export async function recommendMovies(sessionId, answers) {
  // Embed each user’s description
  const embeddings = [];
  for (const ans of answers) {
    const e = await embedAnswer(ans.description);
    embeddings.push(e);
  }

  // Average embedding (group mood)
  const avgEmbedding = embeddings[0].map((_, i) =>
    embeddings.reduce((sum, e) => sum + e[i], 0) / embeddings.length
  );

  // Query Supabase vector search
  const { data, error } = await supabase.rpc("match_movies", {
    query_embedding: avgEmbedding,
    match_count: 5
  });

  if (error) throw error;
  return data;
}
```

### SQL Function for Vector Search
```sql
create or replace function match_movies(
  query_embedding vector(768),
  match_count int default 5
) returns table (
  id bigint,
  title text,
  description text,
  similarity float
) language sql stable as $$
  select
    id,
    title,
    description,
    1 - (movies.embedding <=> query_embedding) as similarity
  from movies
  order by movies.embedding <=> query_embedding
  limit match_count;
$$;
```

