## 🔹 5. Recommendation API

```js
// api/recommend.js
import { GoogleGenerativeAI } from "@google/generative-ai";
import { createClient } from "@supabase/supabase-js";

const genAI = new GoogleGenerativeAI(process.env.GEMINI_API_KEY);
const supabase = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_KEY);

async function embedAnswer(text) {
  const model = genAI.getGenerativeModel({ model: "embedding-001" });
  const result = await model.embedContent(text);
  return result.embedding.values;
}

function cosineSimilarity(a, b) {
  let dot = 0.0, normA = 0.0, normB = 0.0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  return dot / (Math.sqrt(normA) * Math.sqrt(normB));
}

export default async function handler(req, res) {
  try {
    const { answers } = req.body;

    // Embed all user descriptions
    const embeddings = [];
    for (const ans of answers) {
      const e = await embedAnswer(ans.description);
      embeddings.push(e);
    }

    // Average group embedding
    const avgEmbedding = embeddings[0].map((_, i) =>
      embeddings.reduce((sum, e) => sum + e[i], 0) / embeddings.length
    );

    // Get all movies from Supabase
    const { data: movies, error } = await supabase.from("movies").select("*");
    if (error) throw error;

    // Compute similarities
    const scored = movies.map(movie => {
      const sim = cosineSimilarity(avgEmbedding, movie.embedding);
      return { ...movie, similarity: sim };
    });

    // Sort descending
    scored.sort((a, b) => b.similarity - a.similarity);

    res.status(200).json({ recommendations: scored.slice(0, 5) });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
}
```

